/* Inkslide web - ships THIRD_PARTY_NOTICES.md with the build and keeps it honest
 *
 * The notices file lives at the repository root and is generated by
 * `pnpm notices` (scripts/notices.mjs). This plugin copies it into the
 * build (dist/THIRD_PARTY_NOTICES.md, so Electron and Tauri ship it too)
 * and fails the build when a package from node_modules ends up in the
 * bundle without an entry (`### <name> <version>`) in the file: a new or
 * updated dependency needs `pnpm notices` before it can ship.
 */
import { existsSync, readFileSync } from 'node:fs';
import { basename, join } from 'node:path';
import type { Plugin } from 'vite';

type PackageId = { name: string; version: string };
const NODE_MODULES = '/node_modules/';
const manifests = new Map<string, PackageId | null>(); // package dir -> its name and version

/** The package (name@version) a module from node_modules belongs to, or null for first-party code. */
export function packageOf(moduleId: string): PackageId | null {
  const file = moduleId.replace(/^\0/, '').split('?')[0].replace(/\\/g, '/'); // Rollup ids use '/', also on Windows
  const at = file.lastIndexOf(NODE_MODULES) + NODE_MODULES.length;
  if (at < NODE_MODULES.length) return null;
  const parts = file.slice(at).split('/');
  const dir = file.slice(0, at) + parts.slice(0, parts[0].startsWith('@') ? 2 : 1).join('/');
  if (!manifests.has(dir)) {
    const manifest = join(dir, 'package.json');
    const pkg = existsSync(manifest) ? JSON.parse(readFileSync(manifest, 'utf8')) as PackageId : null;
    manifests.set(dir, pkg && { name: pkg.name, version: pkg.version });
  }
  return manifests.get(dir)!;
}

/** The `name@version`s of `packages` that have no `### name version` heading in the notices text. */
export function missingNotices(packages: Iterable<PackageId>, notices: string): string[] {
  const listed = new Set(notices.split('\n').filter(l => l.startsWith('### ')).map(l => l.slice(4).trim()));
  const missing = new Set<string>();
  for (const p of packages) if (!listed.has(`${p.name} ${p.version}`)) missing.add(`${p.name}@${p.version}`);
  return [...missing].sort();
}

/** Emit the notices file and check that it covers every bundled package. */
export function notices(file: string): Plugin {
  return {
    name: 'inkslide-notices',
    apply: 'build',
    generateBundle() {
      if (!existsSync(file)) this.error(`${file} is missing; run: pnpm notices`);
      const text = readFileSync(file, 'utf8');
      const name = basename(file);
      const packages = [...this.getModuleIds()].map(packageOf).filter(p => p !== null);
      const missing = missingNotices(packages, text);
      if (missing.length) this.error(`${name} does not list ${missing.join(', ')}; run: pnpm notices`);
      this.emitFile({ type: 'asset', fileName: name, source: text });
    },
  };
}
